function superEggDrop(k, n) {
  // dp[moves][eggs] = most floors whose threshold can be pinned down
  const dp = [new Array(k + 1).fill(0)];
  let moves = 0;

  while (dp[moves][k] < n) {
    moves++;
    const row = new Array(k + 1).fill(0);
    for (let eggs = 1; eggs <= k; eggs++) {
      const below = dp[moves - 1][eggs - 1];
      const above = dp[moves - 1][eggs];
      row[eggs] = below + above + 1;
    }
    dp.push(row);
  }
  return moves;
}

