function superEggDrop(k, n) {
  // worst[f] = fewest moves for f floors; try every first drop floor x.
  let prev = Array.from({ length: n + 1 }, (_, f) => f); // one egg: test floors bottom-up
  for (let e = 2; e <= k; e++) {
    const cur = new Array(n + 1).fill(0);
    for (let f = 1; f <= n; f++) {
      let best = Infinity;
      for (let x = 1; x <= f; x++) {
        const cost = 1 + Math.max(prev[x - 1], cur[f - x]);
        if (cost < best) best = cost;
      }
      cur[f] = best;
    }
    // If one more egg changed nothing, further eggs cannot change anything either.
    let same = true;
    for (let f = 0; f <= n; f++) if (cur[f] !== prev[f]) { same = false; break; }
    prev = cur;
    if (same) break;
  }
  return prev[n];
}

